<script lang="ts">
import {isLanguage,labels,localizedPath} from '$lib/series/i18n';
let {title,description,path,lang='ko',publishedAt=null,updatedAt=null,translations=[],image=null,seriesPath=null,position=null}=$props<{title:string;description:string;path:string;lang?:string;publishedAt?:string|null;updatedAt?:string|null;translations?:{lang:string;path:string}[];image?:string|null;seriesPath?:string|null;position?:number|null}>();
let schema=$derived({'@context':'https://schema.org','@type':'BlogPosting','@id':'https://jangwook.net'+path+'#article',headline:title,description,url:'https://jangwook.net'+path,mainEntityOfPage:'https://jangwook.net'+path,inLanguage:lang,author:{'@id':'https://jangwook.net/about#author'},publisher:{'@type':'Organization',name:'jangwook.net',url:'https://jangwook.net/'},...(publishedAt?{datePublished:publishedAt}:{}),...(updatedAt?{dateModified:updatedAt}:{}),...(seriesPath?{isPartOf:{'@id':'https://jangwook.net'+seriesPath+'#series'}}:{}),...(position?{position}:{}),...(image?{image:'https://jangwook.net'+image}:{})});
let locale=$derived(isLanguage(lang)?lang:'ko');
let breadcrumbs=$derived({'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'jangwook.net',item:'https://jangwook.net'+localizedPath('/',locale)},{'@type':'ListItem',position:2,name:path.includes('/blog/')?labels[locale].archive:labels[locale].seriesTitle,item:'https://jangwook.net'+(path.includes('/blog/')?'/archive':localizedPath('/series/accessibility',locale))},{'@type':'ListItem',position:3,name:title,item:'https://jangwook.net'+path}]});
</script>
<svelte:head><meta property="og:type" content="article"/>{#if publishedAt}<meta property="article:published_time" content={publishedAt}/>{/if}{#if updatedAt}<meta property="article:modified_time" content={updatedAt}/>{/if}<link rel="alternate" hreflang={lang} href={'https://jangwook.net'+path}/>{#each translations as translation}<link rel="alternate" hreflang={translation.lang} href={'https://jangwook.net'+translation.path}/>{/each}{@html '<script type="application/ld+json">'+JSON.stringify([schema,breadcrumbs]).replace(/</g,'\u003c')+'</script>'}</svelte:head>
